            },
            {
                "$ref": "#/types/list_string"
            },
            {
                "$ref": "#/types/list_integer"
            },
            {
                "$ref": "#/types/list_decimal"
            },
            {
                "$ref": "#/types/list_file"
            },
            {
                "$ref": "#/types/list_dir"
            },
            {
                "$ref": "#/types/list_url"
            }
        ]
    },
    "types": {
        "string": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:(string|text):$"
                },
                "value": {
                    "type": "string"
                }
            }
        },
        "boolean": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:boolean:$"
                },
                "value": {
                    "type": "boolean"
                }
            }
        },
        "integer": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^(basic:integer|data(:[a-z0-9:]+)?):$"
                },
                "value": {
                    "type": "integer"
                }
            }
        },
        "decimal": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:decimal:$"
                },
                "value": {
                    "type": "number"
                }
            }
        },
        "date": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:date:$"
                },
                "value": {
                    "type": "string",
                    "pattern": "^(19|20)\\d\\d-(0[1-9]|1[012])-(0[1-9]|[12][0-9]|3[01])$"
                }
            }
        },
        "datetime": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:datetime:$"
                },
                "value": {
                    "type": "string",
                    "pattern": "^(19|20)\\d\\d-(0[1-9]|1[012])-(0[1-9]|[12][0-9]|3[01]) (?:(?:([01]?\\d|2[0-3]):)?([0-5]?\\d):)?([0-5]?\\d)$"
                }
            }
        },
        "secret": {
            "type": "object",
            "required": [
